-- public.site_for(p_world uuid, p_x0 integer, p_y0 integer, p_w integer, p_h integer, p_species text, p_tries integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.site_for(p_world uuid, p_x0 integer, p_y0 integer, p_w integer, p_h integer, p_species text, p_tries integer DEFAULT 8)
 RETURNS TABLE(x integer, y integer)
 LANGUAGE plpgsql
AS $function$
declare i int; v_x int; v_y int; v_looks int := 0;
        -- A kind of the deep water looks at deep water rather than at ground (`deep_tile`).
        v_deep boolean := coalesce((select deep_water from species_def where id = p_species), false);
begin
  for i in 1 .. greatest(1, p_tries) * 3 loop
    exit when v_looks >= greatest(1, p_tries);
    v_x := p_x0 + floor(random() * p_w)::int;
    v_y := p_y0 + floor(random() * p_h)::int;
    if v_deep then
      if not deep_tile(p_world, v_x, v_y) or on_deed(p_world, v_x, v_y) then continue; end if;
    else
      if not creature_tile_ok(p_world, v_x, v_y) then continue; end if;
      if centre_height(p_world, v_x, v_y) < 2 or on_deed(p_world, v_x, v_y) then continue; end if;
    end if;
    v_looks := v_looks + 1;
    if not suits(p_world, p_species, v_x, v_y) then continue; end if;
    x := v_x;
    y := v_y;
    return next;
    return;
  end loop;
end $function$
